    chain(revealedStartProof(c.child, c.dt), f);
  const withPulls = (p: LocalProof, then: () => Result<Draft, EntityError>): Result<Draft, EntityError> =>
    chain(routeCarriesPull(c.intent.crossJurisdictionRouteId, p.body, c.dt), then);
