    if (!off.ok) return off.error.overrun ? err(off.error.message) : deferred("index 0");
    const arr = ethersArrayText(batch.subarray(off.value), size);
    return !arr.ok && arr.error.overrun ? err(arr.error.message) : ok(arr);
