/** Every signer's bundle signs the manifest. */
const bundlesValid = (q: Quorum, hashes: readonly HashToSign[], sigs: Precommits, ctx: EntityContext): boolean =>
  [...sigs].every(([id, s]) => bundleValid(q, hashes, id, s, ctx));
