  if (ids.includes("") || new Set(ids).size !== ids.length) return txErr("BOARD_VALIDATOR_DUPLICATE_OR_EMPTY");
  const proposer = config.validators[0] ?? "";
  if (!/^0x[0-9a-f]{40}$/i.test(proposer)) return txErr("BOARD_PROPOSER_EOA_REQUIRED");
