const sayMaybe =
  (message: string | undefined): JEvMove =>
  (x) =>
    ok(message === undefined ? x : jevSay(x, message));
const broadcastWhen =
  (wake: boolean): JEvMove =>
  (x) =>
    wake ? jevBroadcast(x) : ok(x);
